// ============================================================================
// mini_soc_iommu_regs -- APB4 register file generated by socgen from
// register_blocks.iommu in socgen/specs/mini_soc.yaml. minimal IOMMU registers
//  - zero wait states, 32-bit data, 12-bit byte address, PSTRB byte lanes
//  - PSLVERR on an unmapped or misaligned offset
//  - hw_* inputs: values of RO registers and set pulses of W1C bits (from the
//    block's logic; tie to 0 for a register-only model)
// ============================================================================
module mini_soc_iommu_regs (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  input  logic [31:0] hw_fault,
  output logic [31:0] q_ctrl,
  output logic [31:0] q_pt_base,
  output logic [31:0] q_scratch
);
  wire        acc   = PSEL & PENABLE;
  wire        wr    = acc & PWRITE;
  wire [31:0] wmask = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic       hit;
  always_comb begin
    hit = 1'b0;
    case (PADDR)
      12'h000: hit = 1'b1;
      12'h004: hit = 1'b1;
      12'h008: hit = 1'b1;
      12'h00C: hit = 1'b1;
      12'h010: hit = 1'b1;
      default: hit = 1'b0;
    endcase
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~hit;

  // 000 ID RO reset 0x494F0100
  // 004 CTRL RW reset 0x00000000
  logic [31:0] r_ctrl;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_ctrl <= 32'h00000000;
    else if (wr && PADDR == 12'h004)
      r_ctrl <= ((r_ctrl & ~wmask) | (PWDATA & wmask)) & 32'h00000003;
  assign q_ctrl = r_ctrl;
  // 008 PT_BASE RW reset 0x00000000
  logic [31:0] r_pt_base;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_pt_base <= 32'h00000000;
    else if (wr && PADDR == 12'h008)
      r_pt_base <= ((r_pt_base & ~wmask) | (PWDATA & wmask)) & 32'hFFFFF000;
  assign q_pt_base = r_pt_base;
  // 00C FAULT W1C reset 0x00000000
  logic [31:0] r_fault;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_fault <= 32'h00000000;
    else r_fault <= ((r_fault & ~((wr && PADDR == 12'h00C) ? (PWDATA & wmask) : 32'h0))
                         | hw_fault) & 32'h00000001;
  // 010 SCRATCH RW reset 0x00000000
  logic [31:0] r_scratch;
  always_ff @(posedge PCLK or negedge PRESETN)
    if (!PRESETN) r_scratch <= 32'h00000000;
    else if (wr && PADDR == 12'h010)
      r_scratch <= ((r_scratch & ~wmask) | (PWDATA & wmask)) & 32'hFFFFFFFF;
  assign q_scratch = r_scratch;

  always_comb begin
    PRDATA = 32'h0;
    if (acc && !PWRITE)
      case (PADDR)
        12'h000: PRDATA = 32'h494F0100;
        12'h004: PRDATA = r_ctrl;
        12'h008: PRDATA = r_pt_base;
        12'h00C: PRDATA = r_fault;
        12'h010: PRDATA = r_scratch;
        default: PRDATA = 32'h0;
      endcase
  end
endmodule
